INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('legacy:mcq-m-01', 'legacy', 'mathematics', 'Calculus & Derivatives', 'medium', 'published', 0, 'Evaluate the definite integral: $\int_{0}^{\pi/2} \sin^2(x) dx$.', '["$\\frac{\\pi}{4}$","$\\frac{\\pi}{2}$","$\\frac{\\pi}{8}$","$1$"]', 0, 'Using the double-angle identity $\sin^2(x) = \frac{1 - \cos(2x)}{2}$, we integrate: $\int_{0}^{\pi/2} \frac{1 - \cos(2x)}{2} dx = \left[ \frac{x}{2} - \frac{\sin(2x)}{4} \right]_{0}^{\pi/2} = \frac{\pi}{4} - 0 = \frac{\pi}{4}$.', 'questions_mathematics/mcq-m-01', 1793267046123, 1793267046123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank1:mcq-m-02', 'bank1', 'mathematics', 'Calculus & Derivatives', 'medium', 'published', 0, 'What is the derivative of $f(x) = x^x$ with respect to $x$ for $x > 0$?', '["$x \\cdot x^{x-1}$","$x^x(1 + \\ln x)$","$x^x \\ln x$","$x^{x-1}(1 + \\ln x)$"]', 1, 'Taking the natural logarithm: $\ln y = x \ln x$. Differentiating implicitly: $\frac{1}{y} \frac{dy}{dx} = \ln x + x \left(\frac{1}{x}\right) = 1 + \ln x$. Thus $\frac{dy}{dx} = x^x(1 + \ln x)$.', 'questions_mathematics/mcq-m-02', 1793267047123, 1793267047123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank2:mcq-m-03', 'bank2', 'mathematics', 'Vectors & Equilibrium', 'easy', 'published', 0, 'If the vectors $\vec{a} = 2\hat{i} + \lambda\hat{j} + \hat{k}$ and $\vec{b} = 4\hat{i} - 2\hat{j} - 2\hat{k}$ are perpendicular, find $\lambda$.', '["$2$","$3$","$4$","$-3$"]', 1, 'Two vectors are perpendicular if and only if their dot product is zero: $\vec{a} \cdot \vec{b} = (2)(4) + (\lambda)(-2) + (1)(-2) = 8 - 2\lambda - 2 = 6 - 2\lambda = 0 \implies 2\lambda = 6 \implies \lambda = 3$.', 'questions_mathematics/mcq-m-03', 1793267048123, 1793267048123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('legacy:mcq-m-04', 'legacy', 'mathematics', 'Calculus & Derivatives', 'easy', 'published', 0, 'Find $\lim_{x \to 0} \frac{\sin(5x)}{\tan(2x)}$.', '["$\\frac{5}{2}$","$\\frac{2}{5}$","$1$","$0$"]', 0, 'Rewrite as $\lim_{x \to 0} \frac{\frac{\sin(5x)}{5x} \cdot 5x}{\frac{\tan(2x)}{2x} \cdot 2x} = \frac{1 \cdot 5}{1 \cdot 2} = \frac{5}{2}$.', 'questions_mathematics/mcq-m-04', 1793267049123, 1793267049123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank1:mcq-m-05', 'bank1', 'mathematics', 'Conic Sections & Hyperbola', 'medium', 'published', 0, 'The eccentricity $e$ of the hyperbola $\frac{x^2}{16} - \frac{y^2}{9} = 1$ is:', '["$\\frac{5}{4}$","$\\frac{4}{5}$","$\\frac{5}{3}$","$\\frac{\\sqrt{7}}{4}$"]', 0, 'For a horizontal hyperbola, $c^2 = a^2 + b^2 = 16 + 9 = 25 \implies c = 5$. The eccentricity is $e = \frac{c}{a} = \frac{5}{4} > 1$.', 'questions_mathematics/mcq-m-05', 1793267050123, 1793267050123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank2:mcq-p-01', 'bank2', 'physics', 'Work, Energy & Power', 'medium', 'published', 0, 'A projectile is launched with velocity $v_0$ at an angle of $45^\circ$ above the horizontal. The ratio of its maximum height $H$ to its horizontal range $R$ is:', '["$\\frac{1}{4}$","$\\frac{1}{2}$","$1$","$\\frac{1}{8}$"]', 0, 'Range $R = \frac{v_0^2 \sin(2\theta)}{g}$ and maximum height $H = \frac{v_0^2 \sin^2(\theta)}{2g}$. At $\theta = 45^\circ$, $\sin(2\theta) = 1$ and $\sin^2(45^\circ) = \frac{1}{2}$, giving $H = \frac{v_0^2}{4g} = \frac{R}{4}$. Therefore, $\frac{H}{R} = \frac{1}{4}$.', 'questions_physics/mcq-p-01', 1793267051123, 1793267051123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('legacy:mcq-p-02', 'legacy', 'physics', 'Electromagnetism & Induction', 'easy', 'published', 0, 'A wire of resistance $R$ is stretched uniformly until its length is doubled. What is its new resistance?', '["$2R$","$4R$","$\\frac{R}{2}$","$\\frac{R}{4}$"]', 1, 'Volume $V = A \cdot L$ remains constant. When length doubles ($L'' = 2L$), cross-sectional area halves ($A'' = A/2$). New resistance $R'' = \rho \frac{L''}{A''} = \rho \frac{2L}{A/2} = 4 \rho \frac{L}{A} = 4R$.', 'questions_physics/mcq-p-02', 1793267052123, 1793267052123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank1:mcq-p-03', 'bank1', 'physics', 'Electromagnetism & Induction', 'easy', 'published', 0, 'The work done by the magnetic Lorentz force $\vec{F} = q(\vec{v} \times \vec{B})$ on a charged particle moving through a constant magnetic field is always:', '["Positive","Negative","Zero","Dependent on the charge sign"]', 2, 'Since $\vec{F} = q(\vec{v} \times \vec{B})$ is always perpendicular to the instantaneous velocity $\vec{v}$, the instantaneous power is $P = \vec{F} \cdot \vec{v} = 0$. Hence the work done on the particle is strictly zero.', 'questions_physics/mcq-p-03', 1793267053123, 1793267053123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank2:mcq-p-04', 'bank2', 'physics', 'Nuclear Physics', 'medium', 'published', 0, 'In a nuclear reactor, heavy water ($D_2O$) is primarily utilized as a:', '["Coolant only","Moderator to slow down fast neutrons","Control rod absorber","Fuel isotope"]', 1, 'Deuterium has a very low neutron capture cross-section and effective kinetic moderation mass, making heavy water an ideal moderator to thermalize fast fission neutrons.', 'questions_physics/mcq-p-04', 1793267054123, 1793267054123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('legacy:mcq-c-01', 'legacy', 'chemistry', 'Aldehydes & Ketones', 'easy', 'published', 0, 'Which reagent is used to differentiate between an aldehyde and a ketone via silver mirror formation?', '["Fehling''s reagent","Tollens'' reagent","Lucas reagent","Benedict''s solution"]', 1, 'Tollens'' reagent (ammoniacal silver nitrate $[Ag(NH_3)_2]^+$) oxidizes aldehydes to carboxylate ions while being reduced to metallic silver (silver mirror). Ketones do not react under standard neutral/mild conditions.', 'questions_chemistry/mcq-c-01', 1793267055123, 1793267055123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank1:mcq-c-02', 'bank1', 'chemistry', 'Chemical Equilibrium', 'medium', 'published', 0, 'For the Haber process $N_2(g) + 3H_2(g) \rightleftharpoons 2NH_3(g)$ with $\Delta H < 0$, which condition shifts equilibrium forward?', '["Increasing temperature and decreasing pressure","Decreasing temperature and increasing pressure","Decreasing pressure only","Adding an inert gas at constant volume"]', 1, 'The reaction is exothermic ($\Delta H < 0$) and produces fewer moles of gas (4 moles reactants $\to$ 2 moles products). By Le Chatelier''s principle, lowering temperature and increasing pressure shifts equilibrium towards $NH_3$.', 'questions_chemistry/mcq-c-02', 1793267056123, 1793267056123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank2:mcq-cs-01', 'bank2', 'computer-science', 'Data Structures & Trees', 'medium', 'published', 0, 'What is the worst-case time complexity of searching for an element in a Balanced Binary Search Tree (AVL tree) with $n$ nodes?', '["$O(1)$","$O(\\log n)$","$O(n)$","$O(n \\log n)$"]', 1, 'An AVL tree maintains height balance such that the height $h \le 1.44 \log_2(n)$. Because tree height is strictly $O(\log n)$, traversal from root to leaf takes $O(\log n)$ in the worst case.', 'questions_computer_science/mcq-cs-01', 1793267057123, 1793267057123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('legacy:mcq-cs-02', 'legacy', 'computer-science', 'Digital Logic & Gates', 'easy', 'published', 0, 'Which logic gate outputs $1$ (HIGH) if and only if an odd number of its inputs are $1$?', '["NAND","NOR","XOR","XNOR"]', 2, 'The Exclusive OR (XOR) gate performs modulo-2 addition: its output is HIGH (1) whenever the parity of 1s among its inputs is odd.', 'questions_computer_science/mcq-cs-02', 1793267058123, 1793267058123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank1:mcq-en-01', 'bank1', 'english', 'Sentence Correction & Idioms', 'medium', 'published', 0, 'Choose the grammatically correct sentence:', '["Neither the students nor the teacher were present in the laboratory.","Neither the students nor the teacher was present in the laboratory.","Neither the students or the teacher was present in the laboratory.","Neither of the students nor the teacher were present in the laboratory."]', 1, 'When using ''neither... nor'', the verb agrees with the subject closest to it. Here, ''the teacher'' is singular, so the singular verb ''was'' is required.', 'questions_english/mcq-en-01', 1793267059123, 1793267059123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank2:mcq-iq-01', 'bank2', 'analytical-reasoning', 'Analytical Reasoning Scenarios', 'hard', 'published', 0, 'If all Bloops are Razzies, and some Razzies are Lurgs, which conclusion MUST logically follow?', '["All Bloops are Lurgs.","Some Bloops are Lurgs.","No Bloop is a Lurg.","None of the above conclusions necessarily follows."]', 3, 'Since only ''some Razzies'' are Lurgs, the subset of Razzies that are Bloops might have zero overlap with the subset of Razzies that are Lurgs. Thus, none of the categorical conclusions is guaranteed.', 'questions_analytical_reasoning/mcq-iq-01', 1793267060123, 1793267060123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('legacy:pool_mathematics_ln_sin_deriv', 'legacy', 'mathematics', 'Calculus & Differentiation', 'easy', 'published', 0, 'What is the derivative of $f(x) = \ln(\sin(x))$ with respect to $x$ for $\sin(x) > 0$?', '["$\\cot(x)$","$\\tan(x)$","$-\\cot(x)$","$\\frac{1}{\\sin(x)}$"]', 0, 'By the chain rule, $\frac{d}{dx}[\ln(\sin(x))] = \frac{1}{\sin(x)} \cdot \cos(x) = \cot(x)$.', 'questions_mathematics/pool_mathematics_ln_sin_deriv', 1793267061123, 1793267061123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank1:pool_mathematics_adj_matrix', 'bank1', 'mathematics', 'Matrices & Determinants', 'medium', 'published', 0, 'If $A$ is a non-singular square matrix of order $3 \times 3$ and $|A| = 4$, then $|\text{adj}(A)|$ is:', '["$16$","$64$","$4$","$12$"]', 0, 'For an $n \times n$ matrix, $|\text{adj}(A)| = |A|^{n-1}$. Here $n = 3$, so $|\text{adj}(A)| = 4^{3-1} = 16$.', 'questions_mathematics/pool_mathematics_adj_matrix', 1793267062123, 1793267062123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank2:pool_mathematics_complex_mod', 'bank2', 'mathematics', 'Trigonometry & Complex Numbers', 'easy', 'published', 0, 'The modulus and principal argument of the complex number $z = 1 + i\sqrt{3}$ are:', '["$r = 2, \\theta = \\frac{\\pi}{3}$","$r = 4, \\theta = \\frac{\\pi}{6}$","$r = 2, \\theta = \\frac{\\pi}{6}$","$r = \\sqrt{2}, \\theta = \\frac{\\pi}{4}$"]', 0, '$r = \sqrt{1^2 + (\sqrt{3})^2} = 2$ and $\tan(\theta) = \sqrt{3} \implies \theta = \frac{\pi}{3}$.', 'questions_mathematics/pool_mathematics_complex_mod', 1793267063123, 1793267063123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank1:pool_physics_de_broglie', 'bank1', 'physics', 'Dawn of Modern Physics', 'easy', 'published', 0, 'What is the de Broglie wavelength $\lambda$ of a particle of mass $m$ moving with speed $v$?', '["$\\lambda = \\frac{h}{mv}$","$\\lambda = hmv$","$\\lambda = \\frac{mv}{h}$","$\\lambda = \\frac{hc}{mv^2}$"]', 0, 'By de Broglie’s relation, matter waves have wavelength $\lambda = \frac{h}{p} = \frac{h}{mv}$.', 'questions_physics/pool_physics_de_broglie', 1793267064123, 1793267064123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank2:pool_physics_parallel_resistors', 'bank2', 'physics', 'Current Electricity', 'medium', 'published', 0, 'Two resistors of $6\,\Omega$ and $3\,\Omega$ are connected in parallel across a $12\text{ V}$ ideal battery. What is the total current $I$ drawn from the battery?', '["$6\\text{ A}$","$2\\text{ A}$","$4\\text{ A}$","$9\\text{ A}$"]', 0, 'Equivalent resistance $R_{\text{eq}} = \frac{6 \times 3}{6 + 3} = 2\,\Omega$. By Ohm’s Law, $I = \frac{V}{R_{\text{eq}}} = \frac{12}{2} = 6\text{ A}$.', 'questions_physics/pool_physics_parallel_resistors', 1793267065123, 1793267065123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank2:pool_physics_ke_momentum', 'bank2', 'physics', 'Work, Energy & Power', 'medium', 'published', 0, 'If the kinetic energy $K$ of a particle of mass $m$ is quadrupled ($4K$), by what factor does its linear momentum $p$ increase?', '["$2$","$4$","$\\sqrt{2}$","$16$"]', 0, 'Since $p = \sqrt{2mK}$, replacing $K$ with $4K$ gives $p'' = \sqrt{2m(4K)} = 2\sqrt{2mK} = 2p$.', 'questions_physics/pool_physics_ke_momentum', 1793267066123, 1793267066123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('legacy:pool_chemistry_ph_calc', 'legacy', 'chemistry', 'Acids, Bases & Salts', 'easy', 'published', 0, 'What is the $\text{pH}$ of a $0.001\text{ M}$ aqueous solution of $\text{HCl}$ at $25^\circ\text{C}$?', '["$3$","$2$","$1$","$11$"]', 0, '$\text{HCl}$ is a strong monoprotic acid, so $[\text{H}^+] = 10^{-3}\text{ M}$ and $\text{pH} = -\log_{10}(10^{-3}) = 3$.', 'questions_chemistry/pool_chemistry_ph_calc', 1793267067123, 1793267067123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank1:pool_chemistry_ideal_gas', 'bank1', 'chemistry', 'States of Matter & Gases', 'medium', 'published', 0, 'According to the ideal gas equation $PV = nRT$, the density $\rho$ of an ideal gas with molar mass $M$ is given by:', '["$\\rho = \\frac{PM}{RT}$","$\\rho = \\frac{RT}{PM}$","$\\rho = \\frac{P}{MRT}$","$\\rho = PMRT$"]', 0, 'Since $n = \frac{m}{M}$ and $\rho = \frac{m}{V}$, substituting into $PV = \frac{m}{M}RT$ yields $\rho = \frac{PM}{RT}$.', 'questions_chemistry/pool_chemistry_ideal_gas', 1793267068123, 1793267068123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank2:pool_chemistry_faraday_electrolysis', 'bank2', 'chemistry', 'Electrochemistry', 'medium', 'published', 0, 'How many coulombs of electric charge $Q$ are required to reduce $1\text{ mol}$ of $\text{Cu}^{2+}$ ions to metallic copper $\text{Cu}(s)$ ($F = 96500\text{ C/mol}$)?', '["$1.93 \\times 10^5\\text{ C}$","$9.65 \\times 10^4\\text{ C}$","$4.825 \\times 10^4\\text{ C}$","$2.895 \\times 10^5\\text{ C}$"]', 0, 'The half-reaction $\text{Cu}^{2+} + 2e^- \to \text{Cu}$ requires $n = 2\text{ mol}$ of electrons, so $Q = nF = 2 \times 96500 = 1.93 \times 10^5\text{ C}$.', 'questions_chemistry/pool_chemistry_faraday_electrolysis', 1793267069123, 1793267069123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank2:pool_chemistry_first_order_halflife', 'bank2', 'chemistry', 'Chemical Kinetics', 'easy', 'published', 0, 'For a first-order chemical reaction with rate constant $k$, the half-life $t_{1/2}$ is given by:', '["$t_{1/2} = \\frac{0.693}{k}$","$t_{1/2} = \\frac{1}{k[A]_0}$","$t_{1/2} = \\frac{[A]_0}{2k}$","$t_{1/2} = \\frac{k}{0.693}$"]', 0, 'From the integrated first-order rate law $\ln\left(\frac{[A]_0}{[A]}\right) = kt$, setting $[A] = \frac{[A]_0}{2}$ gives $t_{1/2} = \frac{\ln 2}{k} \approx \frac{0.693}{k}$.', 'questions_chemistry/pool_chemistry_first_order_halflife', 1793267070123, 1793267070123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('legacy:pool_cs_binary_search', 'legacy', 'computer-science', 'Algorithms & Complexity', 'easy', 'published', 0, 'What is the maximum number of comparisons needed by Binary Search on a sorted array of $n = 1024$ elements?', '["$11$","$1024$","$512$","$64$"]', 0, 'In the worst case, binary search performs $\lfloor \log_2(n) \rfloor + 1 = \log_2(1024) + 1 = 10 + 1 = 11$ comparisons.', 'questions_computer_science/pool_cs_binary_search', 1793267071123, 1793267071123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank1:pool_cs_twos_complement', 'bank1', 'computer-science', 'Number Systems & Digital Logic', 'medium', 'published', 0, 'What is the range of signed integers representable using an $n$-bit two’s complement binary representation?', '["$-2^{n-1} \\text{ to } 2^{n-1} - 1$","$-2^n \\text{ to } 2^n - 1$","$0 \\text{ to } 2^n - 1$","$-(2^{n-1} - 1) \\text{ to } 2^{n-1}$"]', 0, 'An $n$-bit two’s complement integer assigns weight $-2^{n-1}$ to the sign bit, giving a range from $-2^{n-1}$ to $2^{n-1} - 1$.', 'questions_computer_science/pool_cs_twos_complement', 1793267072123, 1793267072123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank2:pool_cs_complete_graph_edges', 'bank2', 'computer-science', 'Data Structures & Graphs', 'medium', 'published', 0, 'How many undirected edges $|E|$ exist in a simple complete graph $K_n$ with $n$ vertices?', '["$\\frac{n(n-1)}{2}$","$n(n-1)$","$n^2$","$2^n$"]', 0, 'Every pair of distinct vertices is connected by a unique edge, so $|E| = \binom{n}{2} = \frac{n(n-1)}{2}$.', 'questions_computer_science/pool_cs_complete_graph_edges', 1793267073123, 1793267073123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank2:pool_cs_subnet_hosts', 'bank2', 'computer-science', 'Computer Networks', 'easy', 'published', 0, 'In IPv4 addressing, how many usable host addresses are available in a $/26$ subnet?', '["$62$","$64$","$30$","$126$"]', 0, 'A $/26$ prefix leaves $32 - 26 = 6$ host bits. Subtracting network and broadcast addresses gives $2^6 - 2 = 64 - 2 = 62$ usable hosts.', 'questions_computer_science/pool_cs_subnet_hosts', 1793267074123, 1793267074123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('legacy:pool_english_subjunctive', 'legacy', 'english', 'Sentence Correction & Grammar', 'medium', 'published', 0, 'Select the grammatically correct completion: "If the experiment ___ repeated $n = 3$ times under identical conditions, the variance would decrease."', '["were","was","has been","will be"]', 0, 'In a Type-$2$ hypothetical conditional ("If + past subjunctive ..., would + base verb"), the subjunctive form $were$ is required for all subjects.', 'questions_english/pool_english_subjunctive', 1793267075123, 1793267075123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank1:pool_english_synonym_ephemeral', 'bank1', 'english', 'Vocabulary & Synonyms', 'easy', 'published', 0, 'Choose the word closest in meaning to **EPHEMERAL** (having a duration $\Delta t \to 0$):', '["Transient","Perpetual","Ubiquitous","Resilient"]', 0, 'Ephemeral means lasting for a very short duration ($\Delta t \to 0$), making **Transient** its exact synonym.', 'questions_english/pool_english_synonym_ephemeral', 1793267076123, 1793267076123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank1:pool_english_parallelism', 'bank1', 'english', 'Sentence Correction & Idioms', 'medium', 'published', 0, 'Identify the sentence that maintains strict grammatical parallelism across all $3$ coordinate clauses:', '["The researcher calibrated the sensor, recorded the voltage $V$, and plotted the linear regression.","The researcher calibrated the sensor, was recording the voltage $V$, and to plot the regression.","The researcher calibrates the sensor, recorded the voltage $V$, and plotting the regression.","Calibrating the sensor, the researcher recorded the voltage $V$ and a plot was made."]', 0, 'Parallelism requires matching verb tenses ($\text{calibrated}, \text{recorded}, \text{plotted}$) across coordinate elements.', 'questions_english/pool_english_parallelism', 1793267077123, 1793267077123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank2:pool_english_preposition_exempt', 'bank2', 'english', 'Prepositions & Usage', 'easy', 'published', 0, 'Choose the correct preposition: "Candidates scoring above the $95^{\text{th}}$ percentile are exempted ___ the preliminary interview."', '["from","of","with","against"]', 0, 'The verb **exempt** takes the fixed preposition **from** ("exempted from $X$").', 'questions_english/pool_english_preposition_exempt', 1793267078123, 1793267078123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('legacy:pool_biology_hardy_weinberg', 'legacy', 'biology', 'Genetics & Evolution', 'medium', 'published', 0, 'In a population in Hardy–Weinberg equilibrium ($p^2 + 2pq + q^2 = 1$), if the recessive allele frequency is $q = 0.3$, what is the frequency of heterozygous carriers ($2pq$)?', '["$0.42$","$0.09$","$0.49$","$0.21$"]', 0, 'Since $p + q = 1$, $p = 1 - 0.3 = 0.7$. The heterozygous frequency is $2pq = 2(0.7)(0.3) = 0.42$.', 'questions_biology/pool_biology_hardy_weinberg', 1793267079123, 1793267079123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('legacy:pool_biology_atp_glycolysis', 'legacy', 'biology', 'Bioenergetics', 'easy', 'published', 0, 'During aerobic glycolysis of $1\text{ mol}$ of glucose ($\text{C}_6\text{H}_{12}\text{O}_6$) to $2\text{ mol}$ of pyruvate, what is the net yield of $\text{ATP}$ molecules by substrate-level phosphorylation?', '["$2\\text{ ATP}$","$4\\text{ ATP}$","$36\\text{ ATP}$","$38\\text{ ATP}$"]', 0, 'Glycolysis invests $2\text{ ATP}$ in the preparatory phase and generates $4\text{ ATP}$ in the payoff phase, giving a net gain of $4 - 2 = 2\text{ ATP}$.', 'questions_biology/pool_biology_atp_glycolysis', 1793267080123, 1793267080123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank1:pool_biology_dna_chargaff', 'bank1', 'biology', 'Biological Molecules & DNA', 'easy', 'published', 0, 'According to Chargaff’s rule, if a double-stranded $\text{DNA}$ molecule contains $22\%$ Adenine ($A = 22\%$), what is the percentage of Cytosine ($C$)?', '["$28\\%$","$22\\%$","$44\\%$","$56\\%$"]', 0, 'Since $A = T = 22\%$, $A + T = 44\%$. The remaining $100\% - 44\% = 56\%$ is split equally between $G$ and $C$, so $C = \frac{56\%}{2} = 28\%$.', 'questions_biology/pool_biology_dna_chargaff', 1793267081123, 1793267081123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank2:pool_biology_mitotic_divisions', 'bank2', 'biology', 'Cell Cycle & Division', 'medium', 'published', 0, 'Starting from a single diploid somatic cell ($2n = 46$), how many cells are produced after $k = 5$ consecutive mitotic divisions ($N = 2^k$)?', '["$32$","$10$","$16$","$64$"]', 0, 'Each mitotic division doubles the cell count, so after $k = 5$ generations there are $N = 2^5 = 32$ cells.', 'questions_biology/pool_biology_mitotic_divisions', 1793267082123, 1793267082123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank2:pool_biology_michaelis_menten', 'bank2', 'biology', 'Enzymes', 'hard', 'published', 0, 'In Michaelis–Menten enzyme kinetics, $v = \frac{V_{\max}[S]}{K_m + [S]}$. When the substrate concentration $[S]$ equals $K_m$, the reaction velocity $v$ is:', '["$\\frac{1}{2} V_{\\max}$","$V_{\\max}$","$2 V_{\\max}$","$\\frac{1}{4} V_{\\max}$"]', 0, 'Substituting $[S] = K_m$ into $v = \frac{V_{\max}[S]}{K_m + [S]}$ gives $v = \frac{V_{\max} K_m}{2 K_m} = \frac{1}{2} V_{\max}$.', 'questions_biology/pool_biology_michaelis_menten', 1793267083123, 1793267083123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('legacy:pool_analytical_sequence_geometric', 'legacy', 'analytical-reasoning', 'Number Series & Patterns', 'easy', 'published', 0, 'Find the next term $a_6$ in the sequence $3, 6, 12, 24, 48, \dots$ where $a_n = 3 \cdot 2^{n-1}$:', '["$96$","$72$","$84$","$108$"]', 0, 'Each term doubles the previous term ($r = 2$), so $a_6 = 3 \cdot 2^{5} = 48 \times 2 = 96$.', 'questions_analytical_reasoning/pool_analytical_sequence_geometric', 1793267084123, 1793267084123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank1:pool_analytical_conditional_contrapositive', 'bank1', 'analytical-reasoning', 'Deductive Logic', 'medium', 'published', 0, 'Given the conditional premise $P \implies Q$ ("If a student scores $\ge 85\%$, they qualify for the merit scholarship"), which statement is logically equivalent?', '["$\\neg Q \\implies \\neg P$ (If a student does not qualify, they scored $< 85\\%$)","$Q \\implies P$ (If a student qualifies, they scored $\\ge 85\\%$)","$\\neg P \\implies \\neg Q$ (If a student scored $< 85\\%$, they do not qualify)","$P \\land \\neg Q$"]', 0, 'A conditional statement $P \implies Q$ is logically equivalent to its contrapositive $\neg Q \implies \neg P$.', 'questions_analytical_reasoning/pool_analytical_conditional_contrapositive', 1793267085123, 1793267085123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank2:pool_analytical_permutations_seating', 'bank2', 'analytical-reasoning', 'Analytical Seating & Arrangements', 'medium', 'published', 0, 'In how many distinct ways can $5$ panel members be seated in a row of $5$ chairs if two specific members $A$ and $B$ must sit adjacent to each other?', '["$48$","$120$","$24$","$60$"]', 0, 'Treat $(A,B)$ as a single block: there are $4! = 24$ block arrangements and $2! = 2$ internal orders for $A$ and $B$, giving $4! \times 2! = 48$.', 'questions_analytical_reasoning/pool_analytical_permutations_seating', 1793267086123, 1793267086123);
INSERT OR REPLACE INTO questions (id, bank_id, subject, topic, difficulty, status, needs_review, question_text, options_json, correct_answer, explanation, source_path, created_at, updated_at) VALUES ('bank2:pool_analytical_pigeonhole', 'bank2', 'analytical-reasoning', 'Quantitative & Logical Puzzles', 'medium', 'published', 0, 'A drawer contains socks of $4$ distinct colors. By the Pigeonhole Principle, what is the minimum number of socks $N$ you must draw blindly to guarantee at least $2$ socks of the same color?', '["$5$","$4$","$6$","$8$"]', 0, 'With $k = 4$ colors (pigeonholes), drawing $k + 1 = 5$ socks guarantees at least one color appears $\ge 2$ times.', 'questions_analytical_reasoning/pool_analytical_pigeonhole', 1793267087123, 1793267087123);
